"use client";

/**
 * Settings — design screen "06 Settings" (design/PuffPAI-Dashboard.dc.html
 * lines 1002-1046). Two-column layout:
 *   left  — H1 + "What stays private" card (sentences generated by the
 *           backend at /system/privacy from the live vault, open outside
 *           services and model address; the real knowledge-pack count from
 *           /system/status; and a real firewall status line);
 *   right — Appearance (theme buttons + accessibility toggles), Wake word,
 *           and shortcut pills to the absorbed pages.
 *
 * Persistence contract (read by the rest of the app):
 *   puff-theme-override        'day' | 'night' | absent(auto)  → html[data-puff-theme]
 *   puffpai_big_touch          '1' | '0' (default off)         → html.puff-big-touch
 *   puffpai_ambient_motion     '1' | '0' (default on)          → html.puff-no-motion (inverse)
 *   puffpai_display_mode       'kiosk' | absent (default)      → html.puff-kiosk
 *   puffpai_show_transcript    '1' | '0' (default on)          → dashboard transcript tile
 * Changes also fire window CustomEvent('puffpai-setting-changed', {detail:{key,value}}).
 */

import { useCallback, useEffect, useState } from "react";
import Link from "next/link";
import MsIcon from "../../_components/MsIcon";
import PairedDevicesCard from "./PairedDevicesCard";
import ToolsmithModelCard from "./ToolsmithModelCard";
import { useAppDispatch, useAppSelector } from "@/app/_stores/hooks";
import { fetchSystemStatus } from "@/app/_stores/systemSlice";
import { apiGet } from "@/app/_lib/api";
import { startWalk } from "@/app/_lib/services/tourService";

/* ── localStorage helpers (SSR-guarded) ─────────────────────── */

function readFlag(key: string, fallback: boolean): boolean {
  try {
    const v = window.localStorage.getItem(key);
    if (v === "1") return true;
    if (v === "0") return false;
  } catch {
    /* storage unavailable */
  }
  return fallback;
}

function writeFlag(key: string, value: boolean) {
  try {
    window.localStorage.setItem(key, value ? "1" : "0");
  } catch {
    /* storage unavailable */
  }
  try {
    window.dispatchEvent(
      new CustomEvent("puffpai-setting-changed", { detail: { key, value } })
    );
  } catch {
    /* older browsers */
  }
}

/** Same clock rule as the boot script in app/layout.tsx. */
function clockTheme(): "day" | "night" {
  const h = new Date().getHours();
  return h >= 7 && h < 19 ? "day" : "night";
}

/** Root-class side effects for the accessibility toggles. */
function applyRootClasses(bigTouch: boolean, motion: boolean) {
  const root = document.documentElement;
  root.classList.toggle("puff-big-touch", bigTouch);
  root.classList.toggle("puff-no-motion", !motion);
}

/* ── Small building blocks ──────────────────────────────────── */

const microLabel: React.CSSProperties = {
  fontFamily: "var(--font-jbmono), monospace",
  fontWeight: 700,
  fontSize: 11,
  letterSpacing: ".14em",
  textTransform: "uppercase",
  color: "var(--text3)",
};

function ToggleRow({
  title,
  sub,
  on,
  onChange,
}: {
  title: string;
  sub: string;
  on: boolean;
  onChange: (next: boolean) => void;
}) {
  return (
    <div
      className="flex items-center justify-between gap-4"
      style={{ padding: "18px 0", borderTop: "1px solid var(--line)" }}
    >
      <div>
        <div
          style={{
            fontFamily: "var(--font-nunito), sans-serif",
            fontWeight: 700,
            fontSize: 17,
            color: "var(--text)",
          }}
        >
          {title}
        </div>
        <div
          style={{
            fontFamily: "var(--font-nunito), sans-serif",
            fontWeight: 500,
            fontSize: 14,
            color: "var(--text3)",
          }}
        >
          {sub}
        </div>
      </div>
      <button
        type="button"
        role="switch"
        aria-checked={on}
        aria-label={title}
        onClick={() => onChange(!on)}
        className="shrink-0 cursor-pointer"
        style={{
          width: 68,
          height: 38,
          borderRadius: 99,
          border: "none",
          background: on ? "var(--pink)" : "var(--chip)",
          position: "relative",
          transition: "background .2s ease",
          padding: 0,
        }}
      >
        <span
          style={{
            position: "absolute",
            top: 4,
            left: on ? 34 : 4,
            width: 30,
            height: 30,
            borderRadius: "50%",
            background: on ? "#fff" : "var(--text3)",
            transition: "left .2s ease, background .2s ease",
          }}
        />
      </button>
    </div>
  );
}

function ZoneRow({
  icon,
  iconColor,
  tint,
  border,
  title,
  children,
}: {
  icon: string;
  iconColor: string;
  tint: string;
  border: string;
  title: string;
  children: React.ReactNode;
}) {
  return (
    <div
      style={{
        padding: 20,
        borderRadius: 22,
        background: `linear-gradient(140deg, ${tint}, transparent)`,
        border: `1px solid ${border}`,
      }}
    >
      <div className="mb-1.5 flex items-center gap-2.5">
        <MsIcon name={icon} size={22} style={{ color: iconColor }} />
        <div
          style={{
            fontFamily: "var(--font-nunito), sans-serif",
            fontWeight: 700,
            fontSize: 19,
            color: "var(--text)",
          }}
        >
          {title}
        </div>
      </div>
      <div
        style={{
          fontFamily: "var(--font-nunito), sans-serif",
          fontWeight: 500,
          fontSize: 16,
          lineHeight: 1.45,
          color: "var(--text2)",
        }}
      >
        {children}
      </div>
    </div>
  );
}

/* ── Page ───────────────────────────────────────────────────── */

const cardStyle: React.CSSProperties = {
  borderRadius: 30,
  border: "1px solid var(--line)",
  background: "var(--card)",
  backdropFilter: "blur(18px)",
  WebkitBackdropFilter: "blur(18px)",
  padding: "26px 28px",
  boxShadow: "var(--shadow)",
};

/** Real /firewall/status payload (the declared service type is stale —
 *  the live endpoint returns backend/lockdown, not status/rules). */

export default function SettingsPage() {
  const dispatch = useAppDispatch();
  const systemStatus = useAppSelector((state) => state.system.status);

  /* Theme override: 'day' | 'night' | null (= auto by clock). */
  const [override, setOverride] = useState<"day" | "night" | null>(null);
  const [bigTouch, setBigTouch] = useState(false);
  const [showTranscript, setShowTranscript] = useState(true);
  const [ambientMotion, setAmbientMotion] = useState(true);
  const [kioskMode, setKioskMode] = useState(false);
  /* What stays private, generated by the backend from the live vault, the
     outside services that are on and the model address (/system/privacy).
     null = still asking; "error" = could not ask, said as such. */
  const [privacyLines, setPrivacyLines] = useState<string[] | null | "error">(null);

  useEffect(() => {
    let alive = true;
    apiGet<{ success: boolean; lines?: string[] }>("/system/privacy")
      .then((r) => {
        if (!alive) return;
        setPrivacyLines(Array.isArray(r?.lines) && r.lines.length ? r.lines : "error");
      })
      .catch(() => alive && setPrivacyLines("error"));
    return () => {
      alive = false;
    };
  }, []);

  /* Mount: hydrate from localStorage, apply root classes, fetch real data. */
  useEffect(() => {
    try {
      const o = window.localStorage.getItem("puff-theme-override");
      if (o === "day" || o === "night") setOverride(o);
    } catch {
      /* storage unavailable */
    }
    const bt = readFlag("puffpai_big_touch", false);
    const tr = readFlag("puffpai_show_transcript", true);
    const am = readFlag("puffpai_ambient_motion", true);
    setBigTouch(bt);
    setShowTranscript(tr);
    setAmbientMotion(am);
    applyRootClasses(bt, am);
    try {
      setKioskMode(
        window.localStorage.getItem("puffpai_display_mode") === "kiosk"
      );
    } catch {
      /* storage unavailable */
    }

    dispatch(fetchSystemStatus());
  }, [dispatch]);

  const pickTheme = useCallback((choice: "day" | "night" | null) => {
    setOverride(choice);
    try {
      if (choice === null) {
        window.localStorage.removeItem("puff-theme-override");
      } else {
        window.localStorage.setItem("puff-theme-override", choice);
      }
    } catch {
      /* storage unavailable */
    }
    document.documentElement.setAttribute(
      "data-puff-theme",
      choice ?? clockTheme()
    );
  }, []);

  const toggleBigTouch = useCallback((next: boolean) => {
    setBigTouch(next);
    writeFlag("puffpai_big_touch", next);
    document.documentElement.classList.toggle("puff-big-touch", next);
  }, []);

  const toggleTranscript = useCallback((next: boolean) => {
    setShowTranscript(next);
    writeFlag("puffpai_show_transcript", next);
  }, []);

  const toggleMotion = useCallback((next: boolean) => {
    setAmbientMotion(next);
    writeFlag("puffpai_ambient_motion", next);
    document.documentElement.classList.toggle("puff-no-motion", !next);
  }, []);

  /* Same key ?puffMode=kiosk writes in the app/layout.tsx boot script —
     'kiosk' or absent, not '1'/'0', so writeFlag doesn't fit. The motion
     governor in css/_theme.css keeps the scene static under html.puff-kiosk
     (Puff still animates while she speaks). */
  const toggleKiosk = useCallback((next: boolean) => {
    setKioskMode(next);
    try {
      if (next) {
        window.localStorage.setItem("puffpai_display_mode", "kiosk");
      } else {
        window.localStorage.removeItem("puffpai_display_mode");
      }
    } catch {
      /* storage unavailable */
    }
    document.documentElement.classList.toggle("puff-kiosk", next);
    try {
      window.dispatchEvent(
        new CustomEvent("puffpai-setting-changed", {
          detail: { key: "puffpai_display_mode", value: next ? "kiosk" : "" },
        })
      );
    } catch {
      /* older browsers */
    }
  }, []);

  const packCount = systemStatus?.knowledge?.library_count;
  /* Bridge line: /system/status firewall summary (same payload the Library
     tile reads), enriched with the lockdown flag from /firewall/status. */
  const fw = systemStatus?.firewall;
  const fwActive = fw?.status === "active" || fw?.status === "enabled";
  const rawWake = systemStatus?.voice?.wake_word?.trim();
  const wakeWord =
    rawWake && rawWake.length > 0
      ? rawWake.replace(/\b\w/g, (c) => c.toUpperCase())
      : "Hey Puff";

  return (
    <section
      style={{
        padding:
          "clamp(16px,2.4vh,26px) clamp(18px,2vw,36px) clamp(18px,2.8vh,30px)",
        animation: "slide-up 0.3s ease-out",
      }}
    >
      <div
        className="grid grid-cols-1 items-start lg:grid-cols-2"
        style={{ gap: "clamp(14px,1.6vw,24px)" }}
      >
        {/* ── Left column ─────────────────────────────────── */}
        <div className="flex min-w-0 flex-col gap-[22px]">
          <div>
            <h1
              style={{
                margin: 0,
                fontFamily: "var(--font-fredoka), sans-serif",
                fontWeight: 600,
                fontSize: "clamp(28px,2.6vw,44px)",
                letterSpacing: "-.8px",
                color: "var(--text)",
              }}
            >
              Settings
            </h1>
            <p
              style={{
                margin: "6px 0 0",
                fontFamily: "var(--font-nunito), sans-serif",
                fontWeight: 500,
                fontSize: 19,
                color: "var(--text2)",
              }}
            >
              What stays on this computer, what is locked away, and what goes out.
            </p>
            {/* The walk around the pages, again (dashboard/_components/Walkthrough). */}
            <button
              type="button"
              data-show-me-around=""
              onClick={startWalk}
              className="flex items-center gap-2"
              style={{
                marginTop: 12,
                fontFamily: "var(--font-nunito), sans-serif",
                fontWeight: 700,
                fontSize: 15,
                padding: "8px 16px",
                borderRadius: 999,
                border: "1px solid var(--line)",
                background: "var(--card2)",
                color: "var(--text)",
                cursor: "pointer",
              }}
            >
              <MsIcon name="tour" size={18} />
              Show me around: what each page is for
            </button>
          </div>

          <div style={cardStyle} className="flex flex-col gap-4">
            <div
              style={{
                fontFamily: "var(--font-fredoka), sans-serif",
                fontWeight: 600,
                fontSize: 24,
                color: "var(--text)",
              }}
            >
              What stays private
            </div>

            {/* Every sentence here comes from the backend's live state. The
                hand-written rows it replaces said files and voice were
                "encrypted at rest" and that requests were "stripped of
                identity"; neither was true. */}
            <ZoneRow
              icon="shield_lock"
              iconColor="var(--magenta)"
              tint="color-mix(in srgb, var(--magenta) 18%, transparent)"
              border="var(--magenta)"
              title="Your private stuff and what leaves your computer"
            >
              {privacyLines === null ? (
                <>Checking…</>
              ) : privacyLines === "error" ? (
                <>I could not check what stays private just now.</>
              ) : (
                <div className="flex flex-col gap-1.5">
                  {privacyLines.map((line, i) => (
                    <p key={i} style={{ margin: 0 }}>
                      {line}
                    </p>
                  ))}
                </div>
              )}
            </ZoneRow>

            <ZoneRow
              icon="menu_book"
              iconColor="var(--sky)"
              tint="color-mix(in srgb, var(--sky) 14%, transparent)"
              border="var(--line)"
              title="Knowledge on this computer"
            >
              {typeof packCount === "number" ? (
                <>
                  <span style={{ fontWeight: 700, color: "var(--text)" }}>
                    {packCount}
                  </span>{" "}
                  offline knowledge {packCount === 1 ? "pack" : "packs"}, read
                  on this computer.
                </>
              ) : (
                <>Offline knowledge packs, read on this computer.</>
              )}
            </ZoneRow>

            {/* Bridge status row. Read-only, and on this build usually EMPTY:
                the number it wants is `firewall` on /system/status, which
                BuildBot's backend does not put there — the firewall/Zone-3
                surface is a HomeBot feature, and there is no firewall page to
                link to either. So the row states that plainly rather than
                implying a reading that failed to arrive. */}
            <div
              className="group flex items-center gap-3"
              style={{
                padding: "16px 20px",
                borderRadius: 20,
                background: fw
                  ? "var(--card2)"
                  : "repeating-linear-gradient(135deg, var(--chip) 0 8px, transparent 8px 16px)",
                border: "1px solid var(--line)",
              }}
            >
              <MsIcon
                name={fw ? (fwActive ? "check_circle" : "shield") : "shield_lock"}
                size={22}
                style={{
                  color: fw
                    ? fwActive
                      ? "var(--mint)"
                      : "var(--lemon)"
                    : "var(--text3)",
                }}
              />
              <div
                className="min-w-0 flex-1"
                style={{
                  fontFamily: "var(--font-nunito), sans-serif",
                  fontWeight: 600,
                  fontSize: 16,
                  color: "var(--text2)",
                }}
              >
                {fw ? (
                  <>
                    Firewall {fw.status}
                    {" · "}
                    {fw.rules_count} rule
                    {fw.rules_count === 1 ? "" : "s"} enforced
                    {fw.blocked_count > 0 ? ` · ${fw.blocked_count} blocked` : ""}
                  </>
                ) : (
                  <>No firewall of its own on this build</>
                )}
              </div>
              <span
                className="flex items-center gap-1 transition-opacity group-hover:opacity-100"
                style={{ ...microLabel, opacity: 0.8 }}
              >
              </span>
            </div>
          </div>
        </div>

        {/* ── Right column ────────────────────────────────── */}
        <div className="flex min-w-0 flex-col gap-5">
          {/* Appearance */}
          <div style={cardStyle}>
            <div
              style={{
                fontFamily: "var(--font-fredoka), sans-serif",
                fontWeight: 600,
                fontSize: 24,
                color: "var(--text)",
                marginBottom: 20,
              }}
            >
              Appearance
            </div>

            <div className="mb-3.5 flex gap-3.5">
              <button
                type="button"
                onClick={() => pickTheme("day")}
                aria-pressed={override === "day"}
                className="flex flex-1 cursor-pointer flex-col items-center justify-center gap-2"
                style={{
                  height: 120,
                  borderRadius: 22,
                  border:
                    override === "day"
                      ? "2px solid var(--pink)"
                      : "1px solid var(--line)",
                  boxShadow:
                    override === "day" ? "0 0 0 4px var(--glow1)" : "none",
                  background: "linear-gradient(150deg,#CFE9F9,#FBDDEE)",
                  color: "#2E2140",
                  fontFamily: "var(--font-nunito), sans-serif",
                  fontWeight: 700,
                  fontSize: 17,
                }}
              >
                <MsIcon name="light_mode" size={30} />
                Blue sky
              </button>
              <button
                type="button"
                onClick={() => pickTheme("night")}
                aria-pressed={override === "night"}
                className="flex flex-1 cursor-pointer flex-col items-center justify-center gap-2"
                style={{
                  height: 120,
                  borderRadius: 22,
                  border:
                    override === "night"
                      ? "2px solid var(--pink)"
                      : "1px solid var(--line)",
                  boxShadow:
                    override === "night" ? "0 0 0 4px var(--glow1)" : "none",
                  background: "linear-gradient(150deg,#150C24,#0B0714)",
                  color: "#F7EEF8",
                  fontFamily: "var(--font-nunito), sans-serif",
                  fontWeight: 700,
                  fontSize: 17,
                }}
              >
                <MsIcon name="dark_mode" size={30} />
                Night sky
              </button>
            </div>

            <button
              type="button"
              onClick={() => pickTheme(null)}
              aria-pressed={override === null}
              className="flex w-full cursor-pointer items-center justify-center gap-2"
              style={{
                height: 46,
                borderRadius: 99,
                marginBottom: 22,
                border:
                  override === null
                    ? "1px solid transparent"
                    : "1px solid var(--line)",
                background:
                  override === null
                    ? "linear-gradient(140deg,var(--pink),var(--magenta))"
                    : "var(--card2)",
                color: override === null ? "#fff" : "var(--text2)",
                fontFamily: "var(--font-nunito), sans-serif",
                fontWeight: 700,
                fontSize: 15,
              }}
            >
              <MsIcon name="schedule" size={20} />
              Auto, follows the clock
            </button>

            <ToggleRow
              title="Big touch mode"
              sub="Larger targets for wall displays"
              on={bigTouch}
              onChange={toggleBigTouch}
            />
            <ToggleRow
              title="Show live transcript"
              sub="Words appear as you speak"
              on={showTranscript}
              onChange={toggleTranscript}
            />
            <ToggleRow
              title="Ambient cloud motion"
              sub="Gentle drift when idle"
              on={ambientMotion}
              onChange={toggleMotion}
            />
            <ToggleRow
              title="Kiosk display"
              sub="Still scene for always-on screens. Saves the GPU for Puff"
              on={kioskMode}
              onChange={toggleKiosk}
            />
          </div>

          {/* Wake word */}
          <div style={cardStyle}>
            <div
              style={{
                fontFamily: "var(--font-fredoka), sans-serif",
                fontWeight: 600,
                fontSize: 24,
                color: "var(--text)",
                marginBottom: 18,
              }}
            >
              Wake word
            </div>
            <div className="flex flex-wrap gap-3">
              <span
                style={{
                  padding: "14px 24px",
                  borderRadius: 99,
                  background:
                    "linear-gradient(140deg,var(--pink),var(--magenta))",
                  color: "#fff",
                  fontFamily: "var(--font-nunito), sans-serif",
                  fontWeight: 700,
                  fontSize: 17,
                }}
              >
                &ldquo;{wakeWord}&rdquo;
              </span>
              <span
                style={{
                  padding: "14px 24px",
                  borderRadius: 99,
                  background: "var(--card2)",
                  border: "1px solid var(--line)",
                  color: "var(--text2)",
                  fontFamily: "var(--font-nunito), sans-serif",
                  fontWeight: 700,
                  fontSize: 17,
                }}
              >
                Push to talk
              </span>
            </div>
            <div
              style={{
                marginTop: 22,
                padding: "18px 20px",
                borderRadius: 20,
                background: "var(--card2)",
                border: "1px solid var(--line)",
                fontFamily: "var(--font-nunito), sans-serif",
                fontWeight: 500,
                fontSize: 16,
                lineHeight: 1.5,
                color: "var(--text2)",
              }}
            >
              Wake-word detection runs on the CPU only. The microphone buffer
              is discarded every 2 seconds unless PuffPAI hears its name.
            </div>
          </div>

          {/* Toolsmith's model: this computer (default) or Anthropic, her choice */}
          <ToolsmithModelCard />

          {/* Paired devices — per-device revocation + the household code/QR */}
          <PairedDevicesCard />

          {/* No Connect-Spotify card: BuildBot's backend carries no
              /api/spotify/* routes, so the whole four-step OAuth dance had
              nothing at the other end. A card that cannot connect is worse
              than no card. */}

          {/* Shortcuts to absorbed pages */}
          <div>
            <div style={{ ...microLabel, margin: "2px 4px 10px" }}>
              Shortcuts
            </div>
            <div className="flex flex-wrap gap-3">
              {[
                { href: "/dashboard?wake=1", icon: "waving_hand", label: "Meet my bot again" },
                { href: "/dashboard/profile", icon: "person", label: "Profile" },
                {
                  href: "/dashboard/documents",
                  icon: "description",
                  label: "My Documents",
                },
              ].map((l) => (
                <Link
                  key={l.href + l.label}
                  href={l.href}
                  className="flex items-center gap-2 no-underline transition-transform hover:-translate-y-0.5"
                  style={{
                    height: 52,
                    padding: "0 22px",
                    borderRadius: 99,
                    background: "var(--card2)",
                    border: "1px solid var(--line)",
                    backdropFilter: "blur(14px)",
                    WebkitBackdropFilter: "blur(14px)",
                    color: "var(--text2)",
                    fontFamily: "var(--font-nunito), sans-serif",
                    fontWeight: 700,
                    fontSize: 15,
                  }}
                >
                  <MsIcon name={l.icon} size={20} />
                  {l.label}
                </Link>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
